// Regenerate backend/src/db/migration-versions.ts from backend/src/db/migrate.ts.
//
// Why a generated file instead of importing the array: the `migrations` array in
// migrate.ts is declared *inside* applyIncrementalMigrations() and spans ~3050 lines
// at function-body indentation. Hoisting it to module scope to make it importable
// would re-indent all of it — an unreviewable diff. So migrate.ts stays the source of
// truth and this emits a small derived module.
//
// Drift is impossible to miss: backend/src/test/migration-chain.test.ts parses
// migrate.ts with the same anchor and fails if the two disagree.
//
// Usage: node scripts/gen-migration-versions.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MIGRATE_PATH = path.join(ROOT, 'backend', 'src', 'db', 'migrate.ts');
const OUT_PATH = path.join(ROOT, 'backend', 'src', 'db', 'migration-versions.ts');

/**
 * Anchored to the array's 6-space `version:` line. A bare /version:\s*(\d+)/g scans the
 * embedded SQL template literals too, and since b7c9122 folded pending/*.sql in verbatim
 * those literals contain doc comments like `-- Register as: { version: 61, ... }` — which is
 * how this repo ended up with three disagreeing "expected schema version" constants.
 */
export function registeredMigrationVersions(source) {
  const start = source.indexOf('const migrations:');
  if (start < 0) throw new Error('migrations array literal not found in migrate.ts');
  const end = source.indexOf('\n  ];', start);
  if (end < 0) throw new Error('migrations array literal is unterminated in migrate.ts');
  return [...source.slice(start, end).matchAll(/^ {6}version: (\d+),$/gm)].map((m) => Number(m[1]));
}

const source = readFileSync(MIGRATE_PATH, 'utf8');
const versions = registeredMigrationVersions(source);

if (versions.length === 0) throw new Error('parsed zero migrations from migrate.ts');
for (let i = 1; i < versions.length; i += 1) {
  if (versions[i] <= versions[i - 1]) {
    throw new Error(`migration chain is not strictly ascending at ${versions[i - 1]} -> ${versions[i]}`);
  }
}

const max = Math.max(...versions);
// Gaps are versions this project never allocated (v1 is the base schema applied from
// shared/src/schema.pg.sql). Recorded so the health check can tell "behind" from
// "failed mid-chain" without hardcoding anything.
const gaps = [];
for (let v = 2; v <= max; v += 1) if (!versions.includes(v)) gaps.push(v);

const out = `// AUTO-GENERATED by scripts/gen-migration-versions.mjs — do not edit by hand.
// Source of truth: backend/src/db/migrate.ts
// Regenerate:    node scripts/gen-migration-versions.mjs
// Guarded by:    backend/src/test/migration-chain.test.ts (fails on drift)

/** Highest registered migration version. ${versions.length} entries. */
export const MAX_MIGRATION_VERSION = ${max};

/** Every registered version, ascending. */
export const MIGRATION_VERSIONS: readonly number[] = ${JSON.stringify(versions)};

/** Versions this project never allocated: ${gaps.length ? gaps.join(', ') : 'none'}. */
export const UNALLOCATED_MIGRATION_VERSIONS: readonly number[] = ${JSON.stringify(gaps)};
`;

writeFileSync(OUT_PATH, out, 'utf8');
console.log(`[migration-versions] ${versions.length} migrations, max v${max}`);
console.log(`[migration-versions] gaps (never allocated): ${gaps.length ? gaps.join(', ') : 'none'}`);
console.log(`[migration-versions] -> ${path.relative(ROOT, OUT_PATH)}`);